package com.cvns.controller;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.cvns.dtos.ResponseDtos.ApiResponse;import com.cvns.service.NotificationService;import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/notifications") @RequiredArgsConstructor public class NotificationController{private final NotificationService s;@GetMapping public ResponseEntity<?> list(){return ResponseEntity.ok(ApiResponse.success("Notifications",s.list()));}@PatchMapping("/{id}/read")public ResponseEntity<?> read(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success("Notification marked read",s.read(id)));}}
